// Pilih tahun grafik Omzet Tahunan: ?tahun=YYYY (default tahun berjalan WITA) → id file "Data Omzet Harian <tahun>" dari tab config master.
// Output 1 item: {tahun, doc, ada_doc, tb_doc, ada_tb, tb_tab, tab_data, zona, hari_ini, tahun_tersedia:[...], gagal:[], catatan:[]}
const baca = node => { for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) { try { return $(n).all().map(it => it.json); } catch (e) {} } return null; };
const gagal = [], catatan = [];
const cfgRows = baca('Baca Config');
if (cfgRows === null || cfgRows.some(x => x && x.error)) gagal.push('Baca Config');
const cfg = {};
for (const r of cfgRows || []) { const k = String(r.key ?? r.Key ?? '').trim(); if (k) cfg[k] = r.value ?? r.Value ?? ''; }
const zona = String(cfg.zona || 'Asia/Makassar');
const now = DateTime.now().setZone(zona);
const wh = (baca('Webhook Omzet Tahunan') || [{}])[0] || {};
const q = wh.query || {};
let tahun = String(q.tahun || '').trim();
if (!/^20\d{2}$/.test(tahun)) { if (tahun) catatan.push('Parameter tahun "' + tahun + '" tidak valid (format YYYY), memakai tahun berjalan'); tahun = String(now.year); }
const tersedia = Object.keys(cfg).map(k => /^data_file_(\d{4})$/.exec(k)).filter(m => m && String(cfg[m[0]] || '').trim()).map(m => +m[1]).sort();
const doc = String(cfg['data_file_' + tahun] || '').trim();
if (!doc) catatan.push('config data_file_' + tahun + ' belum diisi di tab config master');
// Sheet "Target Bulanan" (P&L per bulan, total brand): config target_bulanan_file_<tahun>, bawaan 2026 = sheet "pizza nyantuy target 2026" dari Nana.
const TB_BAWAAN = { '2026': '12oMKjxQ6LUwgi0icBDeV2VhPbRz4LAUoZxMyrjhl8sY' };
const tbDoc = String(cfg['target_bulanan_file_' + tahun] || TB_BAWAAN[tahun] || '').trim();
return [{ json: { tahun: +tahun, doc: doc || 'BELUM-DIISI', ada_doc: !!doc, tb_doc: tbDoc || 'BELUM-DIISI', ada_tb: !!tbDoc, tb_tab: String(cfg.tab_target_bulanan || 'Target Bulanan'), tab_data: String(cfg.tab_data || 'data'), zona,
  hari_ini: now.toISODate(), sekarang: now.toISO({ suppressMilliseconds: true }), tahun_tersedia: tersedia, gagal, catatan } }];

// Susun Omzet Tahunan: realisasi omzet per bulan per outlet (Jan–Des) + target bulanan dari tab target master.
// Realisasi = kolom omzet "Data Omzet Harian <tahun>" tab data (Tunai + QRIS + Ojol, tanpa ongkir; sama dengan dashboard per bulan).
// Kosong = belum ada data (null, bukan 0). Target null = belum diisi di tab target.
const OUTLET_DEFAULT = [['SPO','Sungai Poso'],['GWA','Gowa'],['SDG','Sudiang'],['BRB','Barombong'],['LMB','Limbung'],['PRE','Pare-Pare'],['TML','Tamalate']];
const t = v => (v == null ? '' : String(v).trim());
const num = v => {
  if (typeof v === 'boolean' || v === null || v === undefined) return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let s = t(v).replace(/rp/ig, '').replace(/ /g, '');
  if (!s || s === '-' || s.startsWith('#')) return null;
  if (/^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) ? n : null;
};
const pad = n => String(n).padStart(2, '0');
const toISO = v => {
  if (typeof v === 'number') { if (!(v > 20000 && v < 80000)) return null; const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 864e5); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()); }
  const s = t(v); let m;
  if ((m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s))) return m[1] + '-' + pad(m[2]) + '-' + pad(m[3]);
  if ((m = /^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/.exec(s))) return m[3] + '-' + pad(m[2]) + '-' + pad(m[1]);
  return null;
};
const toYM = v => { if (typeof v === 'number') { const d = toISO(v); return d ? d.slice(0, 7) : ''; } const m = /^(\d{4})-(\d{1,2})/.exec(t(v)); return m ? m[1] + '-' + pad(m[2]) : ''; };
const boolv = v => v === true || ['TRUE', 'YA', '1'].includes(t(v).toUpperCase());

// ---- Sheet "Target Bulanan": blok P&L bulanan bertumpuk. Header blok: ACCOUNT | TARGET <BULAN> | REALISASI <BULAN> | ...
// Baris ACHIEV tiap blok = target omzet (kolom C) & realisasi omzet (kolom D). Realisasi kosong/0 = belum ada (null).
const NAMA_BL = { JANUARI: 1, JAN: 1, FEBRUARI: 2, FEB: 2, MARET: 3, MAR: 3, APRIL: 4, APR: 4, MEI: 5, JUNI: 6, JUN: 6, JULI: 7, JUL: 7, AGUSTUS: 8, AGU: 8, AGT: 8, AGS: 8, AUG: 8,
  SEPTEMBER: 9, SEP: 9, SEPT: 9, OKTOBER: 10, OKT: 10, OCT: 10, NOVEMBER: 11, NOV: 11, DESEMBER: 12, DES: 12, DEC: 12 };
const blDari = v => { const m = /^\s*TARGET\s+([A-Z]+)/i.exec(t(v)); return m ? NAMA_BL[m[1].toUpperCase()] || null : null; };
function parseTB(rows, th) {
  // rows: array [B, C, D] per baris (urutan sheet), atau objek n8n dengan header baris 2 (ACCOUNT, TARGET JANUARI, REALISASI JANUARI)
  let cur = null; const out = {}, catat = [];
  const arr = (rows || []).map(r => {
    if (Array.isArray(r)) return r;
    const ks = Object.keys(r).filter(k => k !== 'row_number'), kA = ks.find(k => /^ACCOUNT$/i.test(k.trim())), kT = ks.find(k => /^TARGET\s/i.test(k.trim())), kR = ks.find(k => /^REALISASI\s/i.test(k.trim()));
    if (cur === null && kT) cur = blDari(kT);
    if (kA) return [r[kA], kT ? r[kT] : null, kR ? r[kR] : null];
    const vs = ks.map(k => r[k]), i = vs.findIndex(v => /^(ACHIEV|ACCOUNT)$/i.test(t(v)));  // header lain: cari label di baris, ambil 2 kolom sesudahnya
    return i < 0 ? [null, null, null] : [vs[i], vs[i + 1], vs[i + 2]];
  });
  for (const [a, c, d] of arr) {
    const A = t(a).toUpperCase();
    const bh = blDari(c); if (bh || A === 'ACCOUNT') { cur = bh; continue; }  // header blok bulan: kolom C "TARGET <BULAN>"
    if (A === 'ACHIEV' && cur) {
      const b = th + '-' + pad(cur);
      const tg = num(c), re = num(d), v = { target: tg !== null && tg > 0 ? Math.round(tg) : null, realisasi: re !== null && re > 0 ? Math.round(re) : null };
      if (out[b]) {  // blok bulan yang sama muncul lagi (bertumpuk): pakai yang realisasinya terisi; bila sama-sama terisi, yang pertama
        catat.push('Target Bulanan: blok bulan ke-' + cur + ' ada lebih dari satu' + (out[b].realisasi == null && v.realisasi != null ? ', dipakai blok yang realisasinya terisi' : ', dipakai blok pertama'));
        if (!(out[b].realisasi == null && v.realisasi != null)) continue;
      }
      out[b] = v;
    }
  }
  const bulan = Object.fromEntries(Object.keys(out).sort().map(b => [b, out[b]]));
  return { bulan, list: Object.keys(bulan).map(b => ({ bulan: b, target: bulan[b].target, realisasi: bulan[b].realisasi, capaian: bulan[b].target && bulan[b].realisasi != null ? Math.round(bulan[b].realisasi / bulan[b].target * 1e4) / 1e4 : null })), catatan: catat };
}

function susun(inp) {
  const { P, outletRows, targetRows, dataRows, gagal, catatan } = inp;
  const th = String(P.tahun), BL = Array.from({ length: 12 }, (_, i) => th + '-' + pad(i + 1));
  let outl = (outletRows || []).filter(r => t(r.kode) && (r.aktif === undefined || r.aktif === '' || boolv(r.aktif)))
    .map(r => ({ kode: t(r.kode).toUpperCase(), nama: t(r.nama) || t(r.kode), urut: num(r.urutan) ?? 99, data_mulai: toISO(r.data_mulai) }));
  if (!outl.length) { outl = OUTLET_DEFAULT.map(([kode, nama], i) => ({ kode, nama, urut: i + 1, data_mulai: null })); if (outletRows !== null) catatan.push('Tab outlet kosong, memakai daftar 7 outlet bawaan'); }
  outl.sort((a, b) => a.urut - b.urut);
  const K = outl.map(o => o.kode), nul = () => Object.fromEntries(K.map(k => [k, null])), nol = () => Object.fromEntries(K.map(k => [k, 0]));
  const M = Object.fromEntries(BL.map(b => [b, { bulan: b, realisasi: nul(), target: nul(), hari: nol(), tgl_terakhir: nul(), hari_dalam_bulan: new Date(Date.UTC(+th, +b.slice(5), 0)).getUTCDate() }]));
  for (const r of targetRows || []) {
    const m = M[toYM(r.bulan)], k = t(r.outlet_kode).toUpperCase(); if (!m || !(k in m.target)) continue;
    const v = num(r.target_bulanan); if (v !== null) m.target[k] = v;
  }
  const seen = new Set(), luar = new Set(); let nBaris = 0, ganda = 0;
  for (const r of dataRows || []) {
    const key = t(r.key); let kode = t(r.outlet_kode).toUpperCase(), tg = toISO(r.tanggal);
    if (key.includes('|')) { const [k, d] = key.split('|'); kode = kode || k.toUpperCase(); tg = toISO(d) || tg; }
    if (!tg) continue; const m = M[tg.slice(0, 7)]; if (!m) continue;
    if (!(kode in m.realisasi)) { if (kode) luar.add(kode); continue; }
    const omzet = num(r.omzet); if (omzet === null) continue;
    const d = +tg.slice(8); if (seen.has(kode + tg)) ganda++; else { seen.add(kode + tg); m.hari[kode]++; }
    m.realisasi[kode] = (m.realisasi[kode] || 0) + omzet; m.tgl_terakhir[kode] = Math.max(m.tgl_terakhir[kode] || 0, d); nBaris++;
  }
  if (ganda) catatan.push(ganda + ' baris tanggal ganda di data ' + th + ', dijumlah');
  if (luar.size) catatan.push('Kode outlet di data tapi tidak ada di tab outlet: ' + [...luar].join(', '));
  if (!nBaris && dataRows !== null) catatan.push('Belum ada omzet ' + th + ' di sheet pusat');
  const tanpaTarget = BL.filter(b => Object.values(M[b].realisasi).some(v => v !== null) && !Object.values(M[b].target).some(v => v !== null)).map(b => +b.slice(5));
  if (tanpaTarget.length) catatan.push('Target belum diisi di tab target untuk bulan ke-' + tanpaTarget.join(', '));
  return { ok: true, versi: 2, tahun: +th, sumber: 'Sheet Pusat · Data Omzet Harian ' + th + ' (omzet Tunai+QRIS+Ojol) · target dari Rekap Omzet (Master)',
    realisasi_cakupan: 'Tunai + QRIS + Ojol, tanpa ongkir', tahun_tersedia: P.tahun_tersedia || [], hari_ini: P.hari_ini || null,
    outlet: outl.map(o => ({ kode: o.kode, nama: o.nama, data_mulai: o.data_mulai })), bulan: BL.map(b => M[b]), baris: nBaris,
    total_brand: inp.tbRows ? Object.assign({ sumber: 'Sheet "' + (P.tb_tab || 'Target Bulanan') + '" (baris ACHIEV: kolom C target, kolom D realisasi) · total brand' }, parseTB(inp.tbRows, th), { dibaca: true }) : null,
    gagal, catatan, generated_at: P.sekarang || null };
}

// ---- jalan (n8n) ----
if (typeof $ === 'function') {
  const baca = node => { for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) { try { return $(n).all().map(it => it.json); } catch (e) {} } return null; };
  const P = (baca('Pilih Tahun') || [{}])[0] || {};
  const gagal = [].concat(P.gagal || []), catatan = [].concat(P.catatan || []);
  const rowsOf = node => { const r = baca(node); if (r === null || r.some(x => x && x.error)) { gagal.push(node); return null; } return r.filter(x => x && Object.keys(x).some(k => k !== 'row_number')); };
  if (!P.tahun) return [{ json: { ok: false, message: 'Tahun tidak terbaca (Baca Config gagal?)', gagal, catatan } }];
  if (gagal.includes('Baca Config')) return [{ json: { ok: false, message: 'Tab config Rekap Omzet (Master) tidak terbaca (cek akses Service Account)', tahun: P.tahun, gagal, catatan } }];
  const inp = { P, gagal, catatan, outletRows: rowsOf('Baca Outlet'), targetRows: rowsOf('Baca Target'),
    tbRows: P.ada_tb ? (rows => { if (rows && !rows.length) { catatan.push('Tab ' + (P.tb_tab || 'Target Bulanan') + ' kosong'); return null; } if (rows === null) catatan.push('Sheet Target Bulanan tidak terbaca — bagikan (Viewer) ke Service Account'); return rows; })(rowsOf('Baca Target Bulanan')) : null,
    dataRows: P.ada_doc === false ? (catatan.push('File data tahun ' + P.tahun + ' belum ada'), []) : rowsOf('Baca Data') };
  if (inp.dataRows === null) return [{ json: { ok: false, message: 'Data omzet sheet pusat tidak terbaca (cek akses Service Account ke file Data Omzet Harian ' + P.tahun + ')', tahun: P.tahun, gagal, catatan } }];
  return [{ json: susun(inp) }];
}
